Promise 很火，没看源码，仅参考平时的使用，造了一个小轮子（有时间再去看源码把）

```js
class PromiseT {
  constructor() {
    this.status = 'running';
    this.val = null;
    this.pendingList = [];
  }
  then(...list) {
    this.pendingList.push(...list);
    return this.run();
  }
  resolve(val) {
    this.status = 'running';
    if (val !== undefined) {
      this.val = val;
    }
    return this.run();
  }
  pending() {
    this.status = 'pending';
  }
  run() {
    if (this.status === 'pending') {
      return this;
    }
    const cal = this.pendingList.shift();
    if (cal === undefined) {
      return this;
    }
    const result = cal(this.val, this);
    if (result === undefined) {
      return this.run();
    }
    if (result.constructor === PromiseT) {
      return result.then(...this.pendingList);
    }
    this.val = result;
    return this.run();
  }
}
```

测试：

